"""Three attributed institutional allegation networks with attached responses.

No skills, inferred ownership or same-name joins. Run from any directory.
"""
import json,pathlib
B=pathlib.Path(__file__).resolve().parent
D={'sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}
ROUTE='/allegations'
CONFIG={
 'lifeline':(['health','disaster-relief','public-funds','justice'],['MH']),
 'scholarship':(['education','welfare','ngo','public-funds','justice'],['UK','UP']),
 'srmf':(['ngo','justice'],['UP','MP','CG']),
}
def geo(case,src):
 states=CONFIG[case][1]
 return [dict(scope='state' if len(states)==1 else 'multi-state',stateCodes=states,localityIds=[],basis='state-association',note='States expressly associated with the public programme or property investigation; not a private address, exact asset pin, or allocation of every payment to every state.',sourceIds=src)]
def dims(case,src,layers):return dict(domains=CONFIG[case][0],layers=layers,geography=geo(case,src),route=ROUTE,sourceIds=src,limitations=[])
def source(i,title,url,publisher,date,locator,summary,tier,limits):
 D['sources'].append(dict(id=i,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt='2026-10-07',locator=locator,summary=summary,tier=tier,limitations=limits))
def entity(i,label,typ,case,src,summary,basis,limits=[]):
 r=dict(id=i,label=label,type=typ,resolved=True,identityBasis=basis,summary=summary,**dims(case,src,['people' if typ=='person' else 'organisations']));r['limitations']=limits;D['entities'].append(r)
def amt(v,u,stage,period):return dict(value=v,currency='INR',unit=u,stage=stage,period=period)
def edge(i,a,b,kind,label,summary,case,src,tier='alleged',date=None,amounts=[],responses=[],limits=[],event=False):
 r=dict(id=i,**{'from':a,'to':b},kind=kind,label=label,summary=summary,tier=tier,status='attributed-allegation' if tier=='alleged' else 'dated-source-record',statusAsOf=date,fromDate=date if event else None,toDate=date if event else None,dateBasis='Exact procedural event date.' if event else 'Status/source date only; underlying programme period is stated in the summary and amount. No one-day role, continuing custody or present guilt is inferred.',alternativeExplanations=['Read the attached response and procedural limits; an enforcement claim, business role or temporary asset restraint does not establish criminal guilt.'],falsifier='Corrected original records, a merits judgment, reconciled payment ledger or proof of different legal identity would require revising or withdrawing this edge.',responseIds=responses,recordIds=[case+'-case'],amounts=amounts,**dims(case,src,['legal'] if kind in ['enforcement-action','court-relief','investigation-direction'] else ['people'] if kind=='role' else ['funding','organisations']));r['limitations']=limits;D['relationships'].append(r)
def record(i,title,summary,case,src,ents,rels,tier,kind,date,response,limits,amounts=[]):
 D['records'].append(dict(id=i,title=title,summary=summary,kind=kind,tier=tier,status='pending-or-procedural-not-final-guilt' if tier=='alleged' else 'response-or-bounded-outcome',statusAsOf=date,fromDate=None,toDate=None,dateBasis='Latest retained source/procedural status, not an assertion that no later proceeding exists. Underlying conduct windows are stated separately.',entityIds=ents,relationshipIds=rels,period={'lifeline':'2020–2022 procurement and payment allegations; 2023–2025 responses and bail','scholarship':'FY2011–12 to FY2016–17 cohort; 15 June 2026 attachment statement','srmf':'2025–2026 disputed Noida transfer and 2026 proceedings; 2010/early2011 origins are historical context'}[case],response=response,alternativeExplanations={'lifeline':['Genuine pandemic staffing services and bed-occupancy billing can explain part of the payments; the bail court questioned the Dean-specific theory and proof.'],'scholarship':['Legitimate scholarships, administrative errors or contested eligibility could explain some records; no court merits determination for this named cohort is retained.'],'srmf':['Competing management claims or a purchaser acting on apparently valid documents are alternatives requiring investigation; buyer status alone does not show knowledge of forgery.']}[case],falsifier='The case must be revised on a contrary merits judgment, authenticated underlying deed/authority, reconciled eligibility and bank records, or corrected identity. Missing response records are not admissions.',amounts=amounts,**{**dims(case,src,['funding','legal','organisations']), 'limitations':limits}))

