  if row.get('id') in ['lifeline-case','lifeline-patkar-status','lh-patkar-bail','lh-receipts-alleged']:
   row['sourceIds']=list(dict.fromkeys(row['sourceIds']+['lifeline-patkar-court-2025']))
  if row.get('id')=='lh-receipts-alleged':
   row['label']='Prosecution: INR324,486,784.90 sanctioned before TDS'
   row['summary']='Bisure §9 and Patkar §6 recount INR324,486,784.90 sanctioned for payment. The later transcription distinguishes this gross amount from TDS and net account credit. It is not a proved loss, kickback or net diverted amount.'
   row['amounts'][0]['stage']='prosecution-alleged sanctioned gross payment before TDS; not net bank credit or proved loss'
  if row.get('id')=='lifeline-patkar-status':
   row['summary']+=' In the court transcription Patkar denies personally forging documents or managing daily attendance/financial records. The court acknowledges prima-facie implications if the prosecution account is taken at face value, but grants conditional bail.'
   row['response']+=' Defence submissions and court qualifications appear in BA3/2025 §§15–21,28–35 and39–54; mirror-only text remains reported.'
  if row.get('id')=='lifeline-case':
   row['summary']=row['summary'].replace('alleged gross receipt is INR324,486,784.90','alleged sanctioned gross amount before TDS is INR324,486,784.90')
   row['limitations'].append('Patkar court transcription separately reports INR318,471,635.72 net credit; this has a two-paise internal subtraction discrepancy and is not added to gross receipts.')
